package com.wego.acesso.api.rest.security;

import io.quarkus.security.identity.SecurityIdentity;
import io.quarkus.vertx.http.runtime.security.HttpSecurityPolicy.CheckResult;
import io.smallrye.mutiny.Uni;
import io.vertx.core.http.HttpServerRequest;
import io.vertx.ext.web.RoutingContext;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.Mockito.when;

/**
 * WEGO-2070 — a barra codificada DUAS vezes ({@code %252F}) tem de cair na mesma regra
 * que barra a forma crua equivalente.
 *
 * <p><strong>O que {@code %252F} é.</strong> Uma barra escrita como {@code %2F} é uma
 * barra percent-codificada: um decode a resolve. Em {@code %252F} o próprio sinal de
 * porcentagem foi codificado ({@code %25} é {@code %}), então o primeiro decode devolve o
 * TEXTO {@code %2F} — que ainda não é barra nenhuma para quem parte o caminho por
 * {@code /}. Com uma passada só de decode, {@code /%252Fapi/v1/x} normalizava para
 * {@code /%2Fapi/v1/x}, não caía sob {@code /api/}, e a política deixava passar; a forma
 * crua equivalente ({@code //api/v1/x}) era barrada. Duas leituras do mesmo caminho, dois
 * vereditos de segurança diferentes.
 *
 * <p><strong>O que este teste segura.</strong> {@link #decodeParaNoPontoFixo()} é o teste
 * de carga: ele exige que a decodificação vá ATÉ o texto parar de mudar, não uma passada
 * fixa. Reduzir {@code decodificar} a uma única passada no código de produção deixa esse
 * teste — e os dois de {@link CheckResult#DENY} — VERMELHOS. Os demais são a cerca em
 * volta: garantem que decodificar mais vezes não estragou o que já funcionava (barra
 * simples, parâmetro de matriz, caminho vizinho {@code /apidocs}, {@code %} literal).
 *
 * <p>JUnit puro com Mockito, sem subir Quarkus: {@code checkPermission} só lê o caminho do
 * {@link RoutingContext} e consulta a identidade, então o mock é fiel ao que a política
 * enxerga em produção.
 */
@ExtendWith(MockitoExtension.class)
class CaminhoNormalizadoPolicyTest {

    /** {@code //api/v1/x} — a forma crua cuja proteção o caminho torto tem de herdar. */
    private static final String FORMA_CRUA = "//api/v1/recurso-sem-anotacao";

    /** A mesma coisa com as barras codificadas UMA vez. */
    private static final String UMA_PASSADA = "/%2Fapi%2Fv1%2Frecurso-sem-anotacao";

    /** A mesma coisa com as barras codificadas DUAS vezes — o caso do card. */
    private static final String DUAS_PASSADAS = "/%252Fapi%252Fv1%252Frecurso-sem-anotacao";

    /** E TRÊS vezes, para provar que o conserto é a família toda, não um caso especial. */
    private static final String TRES_PASSADAS = "/%25252Fapi%25252Fv1%25252Frecurso-sem-anotacao";

    private final CaminhoNormalizadoPolicy politica = new CaminhoNormalizadoPolicy();

    @Mock
    private RoutingContext contexto;

    @Mock
    private HttpServerRequest requisicao;

    @Mock
    private SecurityIdentity identidade;

    // ------------------------------------------------------------------
    // Carga real: o decode tem de ir até o ponto fixo, não uma passada só.
    // ------------------------------------------------------------------

    /**
     * O teste de carga do card. Uma passada de decode devolveria
     * {@code /%2Fapi%2Fv1%2Frecurso-sem-anotacao} e este assert fica VERMELHO.
     */
    @Test
    void decodeParaNoPontoFixo() {
        assertEquals("/api/v1/recurso-sem-anotacao", CaminhoNormalizadoPolicy.normalizar(DUAS_PASSADAS));
        assertEquals("/api/v1/recurso-sem-anotacao", CaminhoNormalizadoPolicy.normalizar(TRES_PASSADAS));
    }

    /**
     * A formulação do critério de aceite: as quatro escritas do MESMO caminho têm de
     * colapsar na mesma forma, para que a regra que barra uma barre todas.
     */
    @Test
    void asQuatroEscritasDoMesmoCaminhoColapsamNaMesmaForma() {
        String alvo = CaminhoNormalizadoPolicy.normalizar(FORMA_CRUA);

        assertEquals(alvo, CaminhoNormalizadoPolicy.normalizar(UMA_PASSADA));
        assertEquals(alvo, CaminhoNormalizadoPolicy.normalizar(DUAS_PASSADAS));
        assertEquals(alvo, CaminhoNormalizadoPolicy.normalizar(TRES_PASSADAS));
    }

    /** A consequência na decisão de autorização: anônimo em {@code %252F} é NEGADO. */
    @Test
    void anonimoEmBarraDuplamenteCodificadaEhNegado() {
        assertSame(CheckResult.DENY, decidir(DUAS_PASSADAS, anonimo()));
    }

    /** Mesma coisa com três passadas. */
    @Test
    void anonimoEmBarraTriplamenteCodificadaEhNegado() {
        assertSame(CheckResult.DENY, decidir(TRES_PASSADAS, anonimo()));
    }

    /** E a forma crua equivalente é negada pela MESMA regra — o "mesmo veredito" do card. */
    @Test
    void anonimoNaFormaCruaEquivalenteEhNegado() {
        assertSame(CheckResult.DENY, decidir(FORMA_CRUA, anonimo()));
    }

    // ------------------------------------------------------------------
    // Cerca: decodificar mais vezes não pode ter estragado o que já valia.
    // ------------------------------------------------------------------

    /** Autenticado no mesmo caminho torto passa — a política nega por anonimato, não por forma. */
    @Test
    void autenticadoEmBarraDuplamenteCodificadaPassa() {
        assertSame(CheckResult.PERMIT, decidir(DUAS_PASSADAS, autenticado()));
    }

    /** As três normalizações antigas continuam valendo (WEGO-2036). */
    @Test
    void normalizacoesAntigasContinuamValendo() {
        assertEquals("/api/v1/operadoras", CaminhoNormalizadoPolicy.normalizar("/api;x=1/v1/operadoras"));
        assertEquals("/api/v1/operadoras", CaminhoNormalizadoPolicy.normalizar("//api//v1/operadoras"));
        assertEquals("/api/v1/operadoras", CaminhoNormalizadoPolicy.normalizar("/api/v1/operadoras?x=1"));
        assertEquals("/api", CaminhoNormalizadoPolicy.normalizar("/api"));
    }

    /**
     * {@code /apidocs} é rota vizinha, NÃO protegida: decodificar mais vezes não pode
     * transformá-la em {@code /api/}.
     */
    @Test
    void rotaVizinhaContinuaLiberadaParaAnonimo() {
        assertSame(CheckResult.PERMIT, decidir("/apidocs/index.html", anonimo()));
        assertSame(CheckResult.PERMIT, decidir("/q/health", anonimo()));
    }

    /**
     * {@code %} literal (escrito {@code %25}) vira {@code %} e PARA ali — se o laço não
     * tivesse ponto de parada, ficaria girando ou consumindo o resto do caminho.
     */
    @Test
    void porcentagemLiteralNaoRealimentaOLaco() {
        assertEquals("/api/v1/100%", CaminhoNormalizadoPolicy.normalizar("/api/v1/100%25"));
        assertEquals("/api/v1/%", CaminhoNormalizadoPolicy.normalizar("/api/v1/%2525"));
    }

    /** Sequência percent inválida não explode nem some: sobra como texto. */
    @Test
    void sequenciaInvalidaSobraComoTexto() {
        assertTrue(CaminhoNormalizadoPolicy.normalizar("/api/v1/%zz").endsWith("%zz"));
    }

    // ------------------------------------------------------------------

    private CheckResult decidir(String caminho, SecurityIdentity quem) {
        when(contexto.normalizedPath()).thenReturn(caminho);
        when(contexto.request()).thenReturn(requisicao);
        when(requisicao.path()).thenReturn(caminho);

        return politica.checkPermission(contexto, Uni.createFrom().item(quem), null)
                .await().indefinitely();
    }

    private SecurityIdentity anonimo() {
        when(identidade.isAnonymous()).thenReturn(true);
        return identidade;
    }

    private SecurityIdentity autenticado() {
        when(identidade.isAnonymous()).thenReturn(false);
        return identidade;
    }
}
